from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
from typing import List

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_data: str = Form(...), files: List[UploadFile] = File(...)):
    return {"form_data": form_data, "files": [f.filename for f in files]}

client = TestClient(app)

def test_form_then_files():
    files = [("files", ("test1.txt", b"hello1")), ("files", ("test2.txt", b"hello2"))]
    data = {"form_data": "test_form"}
    # TestClient.post handles files as a list of tuples for multiple files with same name
    response = client.post("/test", data=data, files=files)
    print(f"Response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_files()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
